//! 🎟️ Exact native preparation receipts remain independent of display checkpoints and parent terminal state.
use super::{ArtifactStoreOneItemCheckpoint,ArtifactStoreOneItemPreparationStep as Step,ArtifactStoreOneItemGrant,RetainedCloneProgress,validate_original_preparation_step};
use semio_framework_trace::observe_heap_allocations_on_this_thread;
#[test]
fn original_store_preparation_receipt_preserves_all_currencies_and_rejects_overspending(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let checkpoint=ArtifactStoreOneItemCheckpoint{cursor:42,completed_items:17,completed_bytes:65536,digest:[9;32]};
 for row in fixture["cases"].as_array().unwrap(){let n=|part:&str,axis:&str|row[part][axis].as_u64().unwrap()as usize;let grant=ArtifactStoreOneItemGrant{maximum_items:n("grant","items"),maximum_copy_bytes:n("grant","copy"),maximum_capacity_bytes:n("grant","capacity"),maximum_release_bytes:n("grant","release"),maximum_depth:n("grant","depth")};assert_eq!(ArtifactStoreOneItemGrant::from_retained(grant.retained_grant()),grant);let receipt=RetainedCloneProgress{copied_items:n("receipt","items"),copied_bytes:n("receipt","copy"),retained_capacity_bytes:n("receipt","capacity"),released_bytes:n("receipt","release")};
  for prepared in [false,true]{let original=if prepared{Step::Prepared(checkpoint,receipt)}else{Step::Progress(checkpoint,receipt)};let(result,heap)=observe_heap_allocations_on_this_thread(||validate_original_preparation_step(original,grant,prepared));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(result.is_ok(),row["accepted"].as_bool().unwrap());if let Ok(actual)=result{assert_eq!(actual,original);assert_eq!(actual.ownership_progress(),receipt);}}
 }
 let zero=ArtifactStoreOneItemGrant{maximum_items:0,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:0};let(error,heap)=observe_heap_allocations_on_this_thread(||validate_original_preparation_step(Step::Prepared(checkpoint,Default::default()),zero,false).unwrap_err());assert_eq!(error.kind,semio_framework_value::ValueRefusalKind::InvariantViolated);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(validate_original_preparation_step(Step::Blocked,zero,false).unwrap(),Step::Blocked);eprintln!("[DEBUG] Actual Store preparation validates fourteen original receipts, four consumed currencies and independent depth0, no checkpoint-derived credit, missing Prepared-root rejected, pureheap0");
}

#[test]
fn original_ephemeral_shared_transfer_admits_before_take_and_preserves_child_receipt(){
 use super::{ArtifactEphemeralOneItemPreparation,ArtifactEphemeralOneItemPreparationRequest,ArtifactEphemeralBaseRead,ArtifactEphemeralBaseOwner,ArtifactOwnedValueRetirementFactory};use std::sync::Arc;
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let full=ArtifactStoreOneItemGrant{maximum_items:1,maximum_copy_bytes:256,maximum_capacity_bytes:8192,maximum_release_bytes:0,maximum_depth:2};let cleanup=ArtifactStoreOneItemGrant{maximum_items:1,maximum_copy_bytes:256,maximum_capacity_bytes:8192,maximum_release_bytes:131072,maximum_depth:32};
 for row in fixture["transferCases"].as_array().unwrap(){for cancel in [false,true]{
  let(mut owner,setup)=observe_heap_allocations_on_this_thread(||{let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(semio_framework_value::retirement::OwnedValueRetirementFactory::<String>::default());let mut original=String::with_capacity(65536);original.push_str("unchanged original λ🙂");let request=ArtifactEphemeralOneItemPreparationRequest{operation:semio_framework_job::OperationId(701),generation:semio_framework_job::Generation(9),base:ArtifactEphemeralBaseRead(ArtifactEphemeralBaseOwner::Transient(Arc::new(String::new()))),mutation:original};let task=Box::new(super::ephemeral_transfer::TransferTask{transfer:std::convert::identity::<String>});super::ephemeral_preparation::ArtifactEphemeralTaskPreparation::new(request,task,factory.clone(),factory)});
  let n=|axis:&str|row["grant"][axis].as_u64().unwrap()as usize;let grant=ArtifactStoreOneItemGrant{maximum_items:n("items"),maximum_copy_bytes:n("copy"),maximum_capacity_bytes:n("capacity"),maximum_release_bytes:n("release"),maximum_depth:n("depth")};let mut births=setup.requested_bytes;let mut releases=setup.released_bytes;
  let(step,heap)=observe_heap_allocations_on_this_thread(||owner.advance(grant).unwrap());let receipt=step.ownership_progress();assert!(receipt.fits(grant.retained_grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));births+=heap.requested_bytes;releases+=heap.released_bytes;let accepted=matches!(step,Step::Prepared(..));assert_eq!(accepted,row["accepted"].as_bool().unwrap());
  if !accepted{assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));if !cancel{let(step,heap)=observe_heap_allocations_on_this_thread(||owner.advance(full).unwrap());let receipt=step.ownership_progress();assert!(matches!(step,Step::Prepared(..)));assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));births+=heap.requested_bytes;releases+=heap.released_bytes;}}
  if let Some(prepared)=owner.prepared(){assert_eq!(prepared.next_root.as_str(),"unchanged original λ🙂");let pointer=Arc::as_ptr(&prepared.next_root);let(zero,heap)=observe_heap_allocations_on_this_thread(||owner.advance(ArtifactStoreOneItemGrant{maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1}).unwrap());assert_eq!(zero.ownership_progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(Arc::as_ptr(&owner.prepared().unwrap().next_root),pointer);}
  let((),heap)=observe_heap_allocations_on_this_thread(||{owner.cancel();owner.begin_close()});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  for turn in 0..2048{if owner.terminal_is_empty(){break;}let(step,heap)=observe_heap_allocations_on_this_thread(||owner.close_step(cleanup).unwrap());let receipt=step.progress();assert!(receipt.fits(cleanup.retained_grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));births+=heap.requested_bytes;releases+=heap.released_bytes;assert!(turn<2047);}
  assert!(owner.terminal_is_empty());assert_eq!(births,releases);let((),heap)=observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] Actual original ephemeral transfer accepted={accepted} canceled={cancel}, original+births={births} physicalrelease={releases}, independentfiveaxis, no-workreceipt0, finalDrop0");
 }}
}
